    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 nonce) public payable {
        require(nonce == nonce);
        address owner = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        bool callerIsOwner = (owner == address(this));
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted != callerIsOwner);
    }

    receive() external payable {}
}

