pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 nonce) internal {
        vm.assume(nonce == nonce);
        address owner;
        try c.smartfix_owner() returns (address __r) { owner = __r; } catch { return; }
        bool callerIsOwner = (owner == address(this));
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted != callerIsOwner);
    }

    function testFuzz_run(uint256 nonce) public {
        _run(nonce);
    }

    receive() external payable {}
}
